# -*- coding: utf-8 -*-
import json

t = {}

t["396"] = "Điều 2 khoản 5 và Điều 13 Luật Giao thông đường bộ, Thông tư thi hành Luật Giao thông đường bộ Phụ lục 6 số thứ tự 501. Dù là vạch đôi hay vạch đơn đều không được vượt qua, và khi xe buýt dừng lại để đón trả khách thì không được vượt xe. Ngoài ra, vạch tim đường được kẻ ở nơi có chiều rộng lòng đường từ 6 mét trở lên."
t["397"] = "Trên đường cao tốc một chiều 3 làn, làn số 2 thuộc làn bên trái nên các loại xe được phép đi là xe con và xe khách cỡ nhẹ, nhỏ, trung. (Thông tư thi hành Luật Giao thông đường bộ Phụ lục 9)"
t["398"] = "Thông tư thi hành Luật Giao thông đường bộ [Phụ lục 9] Tiêu chuẩn xe lưu thông theo làn đường. Trên đường cao tốc một chiều 2 làn là mọi xe ô tô muốn vượt xe. Tuy nhiên, trong trường hợp buộc phải đi với tốc độ dưới 80 km/h do tình trạng đường như lưu lượng xe tăng, thì dù không phải trường hợp vượt xe cũng có thể lưu thông."
t["399"] = "Điều 60 Luật Giao thông đường bộ (Cấm đi vào lề đường v.v.), Điều 64 Luật Giao thông đường bộ (Cấm dừng và đỗ xe trên đường cao tốc v.v.), Nghị định thi hành Luật Giao thông đường bộ Phụ lục 8 khoản 19. Xe con và tương đương 60.000 won."
t["400"] = "Là làn đường ở phần gần làn số 1 khi chia đôi các làn đường trừ làn số 1. Tuy nhiên, nếu số làn đường trừ làn số 1 là số lẻ thì loại trừ làn ở giữa."
t["401"] = "Thông tư thi hành Luật Giao thông đường bộ [Phụ lục 9] Mọi xe đều có thể đi ở làn bên phải so với làn được chỉ định. Nghị định thi hành Luật Giao thông đường bộ Phụ lục 8 khoản 39. Xe con và tương đương 40.000 won. Thông tư thi hành Luật Giao thông đường bộ Phụ lục 28 mục 3 khoản 21. Điểm phạt 10 điểm."
t["402"] = "Trên đường cao tốc, khi xe con vượt xe thì phải sử dụng làn số 1, và sau khi vượt xong phải chạy ở làn chạy được chỉ định. (Thông tư thi hành Luật Giao thông đường bộ Phụ lục 9)"
t["403"] = "Khi vượt xe, có thể đi ở làn bên trái ngay cạnh làn được chỉ định theo tiêu chuẩn lưu thông. (Thông tư thi hành Luật Giao thông đường bộ Phụ lục 9)"
t["404"] = "Trường hợp taxi tạm thời đi vào để đón hoặc trả khách trong phạm vi không gây cản trở cho các xe lưu thông ở làn đường riêng. Trong trường hợp này, người lái taxi phải rời khỏi làn đường riêng ngay khi khách lên hoặc xuống xe. (Điều 10 khoản 2 Nghị định thi hành Luật Giao thông đường bộ và Phụ lục 1 của Nghị định đó)"
t["405"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 1"
t["406"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 9. Trên đường cao tốc một chiều 3 làn, làn chạy của xe con và xe khách cỡ nhẹ, nhỏ, trung là làn số 2 bên trái, và khi vượt xe ở làn số 2 thì phải sử dụng làn số 1 để vượt."
t["407"] = "Có thể sử dụng làn số 1 để vượt xe."
t["408"] = "① Điều 21 (Phương pháp vượt xe v.v.) khoản 1 Luật Giao thông đường bộ: mọi người lái xe khi muốn vượt xe khác thì phải đi về bên trái của xe phía trước. ② Thông tư thi hành Luật Giao thông đường bộ Phụ lục 6, vạch tim đường (vạch kẻ đường số 501). ③ Điều 2 (Định nghĩa) khoản 5 Luật Giao thông đường bộ: khi có làn đường biến thiên, vạch đứt màu vàng nằm ngoài cùng bên trái theo hướng đi mà đèn tín hiệu chỉ định được coi là vạch tim đường. ④ Theo Điều 16 khoản 1 và Điều 39 khoản 1 Luật Giao thông đường bộ và Phụ lục 9 của Thông tư thi hành, khi vượt xe có thể đi ở làn ngay bên trái theo tiêu chuẩn xe lưu thông theo làn đường, nên trên đường cao tốc một chiều từ 3 làn trở lên, xe đang chạy ở làn bên phải không thể tiến vào tới làn số 1 mà chỉ có thể sử dụng làn ngay bên cạnh để vượt xe."
t["409"] = "Điều 16 Thông tư thi hành Luật Giao thông đường bộ: thứ tự làn đường được tính làn gần vạch tim đường là làn số 1. Tuy nhiên, trên đường một chiều thì tính từ bên trái đường là làn số 1."
t["410"] = "Thông tư thi hành Luật Giao thông đường bộ Phụ lục 9. Trên đường cao tốc một chiều từ 3 làn trở lên, làn số 1 dành cho xe con muốn vượt và xe khách cỡ nhẹ, nhỏ, trung muốn vượt (tuy nhiên, trong trường hợp buộc phải đi với tốc độ dưới 80 km/h do tình trạng đường như lưu lượng xe tăng thì dù không phải trường hợp vượt xe cũng có thể lưu thông), làn bên trái dành cho xe con và xe khách cỡ nhẹ, nhỏ, trung, làn bên phải dành cho xe khách cỡ lớn, xe tải, xe chuyên dùng và máy xây dựng theo Điều 2 khoản 18 mục b của Luật có thể lưu thông."
t["411"] = "Nghị định thi hành Luật Giao thông đường bộ Phụ lục 1 (Các loại làn đường riêng và xe được phép đi vào làn đường riêng). Các loại làn đường riêng được chia thành 3 loại: làn riêng cho xe buýt, làn riêng cho xe nhiều người, làn riêng cho xe đạp."
t["412"] = "Lốp bản rộng, áp suất lốp thấp và gai lốp (ta-lông) bị mòn thì khả năng xảy ra hiện tượng màng nước cao, còn lốp mới thì giảm khả năng xảy ra hiện tượng màng nước."
t["413"] = "Khi xe bị trượt trên đường băng, việc đánh vô lăng theo hướng xe đang trượt là an toàn."
t["414"] = "Khi lái xe trên đường có sương mù mà vẫn đảm bảo được tầm nhìn ở mức độ nào đó, hãy đi chậm bằng cách sử dụng các mốc địa hình có thể xác định vị trí xe như lan can bảo vệ (guardrail), vạch tim đường, vạch làn đường."
t["415"] = "Vì đường tuyết hoặc đường băng trơn trượt nên khi dừng lại, việc giảm tốc bằng phanh động cơ rồi đạp phanh chân nhiều lần chia nhỏ là an toàn."
t["416"] = "Hầm chui có nhiều yếu tố nguy hiểm nên việc kiểm tra thông tin thảm họa sẽ giúp lái xe an toàn."
t["417"] = "Black ice là hiện tượng hình thành lớp màng băng mỏng khó nhìn thấy bằng mắt, thường xảy ra ở trên cầu, cửa hầm, đường có bóng râm."
t["418"] = "Hướng dẫn hành động của người dân trên Cổng thông tin an toàn thảm họa quốc dân của Bộ Nội vụ và An toàn - Trước khi lốp xe ngập 2/3, hãy di chuyển xe đến nơi an toàn, và nếu bị ngập nước thì dùng thanh sắt của gối tựa đầu ghế lái đập vỡ kính cửa để thoát ra - Nếu không đập vỡ được kính, hãy chờ đến khi chênh lệch mực nước trong và ngoài xe còn dưới 30cm rồi nhanh chóng thoát ra vào khoảnh khắc cửa xe mở được - Khi mưa 100mm mỗi giờ thì không thể nhận diện được biển báo cách xa hơn 100 mét, hãy di chuyển xe đến nơi an toàn và chờ một lúc cho đến khi mưa giảm - Khi nước bắt đầu đọng trong hầm chui thì tuyệt đối không đi vào, nếu đã đi vào thì bỏ xe lại và nhanh chóng thoát ra - Khi nước tràn qua cầu thì tuyệt đối cấm đi vào, hãy đi vòng hoặc chờ ở nơi an toàn - Khi xe bị cô lập, hãy mở cửa phía ngược với dòng nước xiết hoặc đập vỡ cửa kính để thoát ra ※ Kính cửa xe có độ đàn hồi nhất định nên nếu đập vào phần giữa để làm vỡ thì tốn nhiều sức, vì vậy phải đập vào phần góc (thẻ tin tức trên blog chính thức của Tổng công ty An toàn Giao thông Hàn Quốc) ※ Khi xe bị ngập nước, sau khi nhanh chóng thoát ra hãy lánh lên nơi cao hơn mực nước, hoặc leo lên nóc xe chờ cứu hộ. (thẻ tin tức trên blog chính thức của Cục Phòng cháy chữa cháy)"
t["419"] = "Khi phanh bị vỡ không phanh được thì khả năng xảy ra tai nạn lớn do đâm vào xe phía trước hoặc va chạm với xe hướng ngược lại là rất cao. Khi phanh bị vỡ, đừng hoảng loạn mà hãy chuyển về số thấp để giảm tốc rồi cho thân xe va vào lan can bảo vệ hoặc tường v.v. để dừng lại, đó là cách phòng ngừa tai nạn thứ cấp."
t["420"] = "Cách ứng phó đúng khi chứng kiến hỏa hoạn do tai nạn ô tô v.v. trong lúc đi qua hầm ① Nếu xe cộ có thể lưu thông thì nhanh chóng thoát ra khỏi hầm. ② Dù có hỏa hoạn nhưng nếu vẫn đảm bảo tầm nhìn và có thể lưu thông thì cứ tiếp tục di chuyển xe ra ngoài. ③ Khi không đảm bảo tầm nhìn và xe bị ùn tắc hoặc không thể lưu thông thì dừng xe ở điểm đỗ khẩn cấp hoặc lề đường. Tắt máy, để nguyên chìa khóa cắm ở ổ rồi xuống xe. Dùng điện thoại di động hoặc điện thoại khẩn cấp trong hầm gọi báo 119 v.v., và nếu có người bị thương thì chăm sóc họ. Nếu khói ra nhiều thì cúi thấp người hết mức và di chuyển theo hướng ngược với khói theo đèn chỉ dẫn trong hầm."
t["421"] = "① Nếu giữ nguyên tốc độ như trước khi vào đường cong mà chạy đều tốc thì có nguy cơ văng khỏi đường. ② Sau khi vào đường cong phải hạ tỷ số truyền (về số thấp) mới giảm được lực ly tâm. ③ Trên đường cong, xe dẫn động cầu trước có thể xảy ra hiện tượng thiếu lái (understeer). ④ Để giảm hiện tượng thừa lái (oversteer) trên đường cong, phải dùng kỹ thuật đánh lái ngược (counter steer), tức là đánh vô lăng theo hướng ngược với hướng đang lái để giữ thăng bằng cho xe."
t["422"] = "Hiện tượng phanh chân bị sử dụng quá nhiều khiến nhiệt ma sát sinh ra bọt khí trong dầu phanh làm không phanh được gọi là hiện tượng khóa hơi (Vapor lock)."
t["423"] = "Nếu bật đèn pha (đèn chiếu xa) thì các hạt nước li ti trong sương mù sẽ khúc xạ, phân tán ánh sáng làm cản trở tầm nhìn của người lái xe đối diện, nên giữ đèn sương mù và đèn cốt (đèn chiếu gần) là cách tốt hơn."
t["424"] = "Đây là một trong những hiện tượng đóng băng mặt đường, được gọi là black ice hoặc clear ice, chỉ hiện tượng hình thành lớp màng băng mỏng như được phủ lên bề mặt đường. Bao gồm hiện tượng tuyết và hơi ẩm thấm qua các khe nứt của nhựa đường, quyện lẫn với khói bụi, bụi bẩn trong không khí rồi đóng băng đen lại. Chủ yếu xảy ra vào mùa đông lạnh ở những đoạn đường có bóng râm và nhiệt độ thấp như trên cầu, cửa hầm, đường có bóng râm, khúc cua núi khuất nắng v.v. Vì khó nhận biết bằng mắt thường nên nguy cơ tai nạn rất cao."
t["425"] = "① Đường lát bê tông xảy ra đóng băng nhiều hơn đường lát nhựa. ② Đường lát nhựa tan băng chậm hơn đường bê tông. ③, ④ Trong tình trạng đóng băng cùng điều kiện, hệ số ma sát mặt đường của đường lát bê tông và đường lát nhựa là 0,3, nhỏ hơn một nửa so với hệ số ma sát của mặt đường khô."
t["426"] = "Khi xảy ra động đất, trước tiên hãy bật radio tập trung nghe phát thanh về thảm họa, và để nhường trống phần giữa đường cho xe cứu thương, xe cảnh sát sử dụng đường trước, hãy đỗ chiếc xe đang lái sát vào mép phải của đường; đề phòng trường hợp phải di dời xe đã đỗ, hãy để nguyên chìa khóa cắm ở ổ, chỉ mang theo hành lý tối thiểu, đỗ xe sát mép đường rồi lánh nạn. <Hướng dẫn lánh nạn động đất của Bộ Nội vụ và An toàn>"
t["427"] = "Gió mạnh hoặc gió giật dễ xảy ra ở vùng núi hoặc nơi cao, trên cầu, cửa hầm v.v. nên cần chú ý khi đi qua những khu vực đó. Trong tình huống này, phải nắm chắc vô lăng bằng cả hai tay để giữ làn đường và giảm tốc độ mới an toàn. Ngoài ra, gió mạnh hoặc gió giật có thể làm đổ biển báo, đèn tín hiệu, cây ven đường nên không đỗ xe gần đó."
t["428"] = "Đường sỏi đá có mặt đường không bằng phẳng, và do sỏi đá có thể làm hư hại lốp hoặc khiến vô lăng bị xê dịch mạnh. Hãy đánh lái nhỏ nhất có thể đồng thời giảm tốc độ, sử dụng số thấp để giữ tốc độ ổn định, và áp suất lốp thích hợp hơi thấp một chút thì lực bám tốt hơn và giảm thiểu chấn động, có lợi cho việc lái xe."
t["429"] = "① Khi phanh gấp, do ma sát giữa lốp và mặt đường, xảy ra hiện tượng xe chúi đầu về phía trước. ② Trên đường mưa, lực ma sát giữa lốp và mặt đường giảm nên quãng đường phanh dài ra. ③ Xảy ra hiện tượng màng nước và hiện tượng phanh lệch khiến hướng lái bị chệch và có thể văng khỏi làn đường. ④ Lốp xe càng mòn thì quãng đường phanh càng dài."
t["430"] = "① Nếu vòng tua máy (RPM) cao thì tiêu hao nhiên liệu lớn. ② Ở đỉnh dốc lên hãy đi chậm, chứ không nhất thiết phải dừng lại hẳn. ③ Nên mở rộng khoảng cách với xe phía trước và giữ khoảng cách an toàn. ④ Nên chạy bằng số thấp có lực động cơ lớn hơn là số cao có lực động cơ nhỏ."
t["431"] = "Trên đường xuống dốc, do trọng lượng thân xe và lực quán tính có thể gây áp lực quá mức lên phanh chân, nên nhất thiết phải sử dụng số thấp (phanh động cơ) để giảm áp lực lên phanh chân trong khi lái xe."
t["432"] = "① Cần lái xe an toàn thông qua thông tin đóng băng đường dựa trên thông tin thời tiết và tình hình giao thông. ③ Sau khi rải chất tan tuyết, tuyết đã tan có nguy cơ đóng băng trở lại cùng với tuyết rơi, nước muối v.v. nên phải giảm tốc độ khi lái xe."
t["433"] = "Ổ gà (pothole) là hiện tượng nền đường bị yếu đi do nước mưa và phát sinh vết nứt, khiến bề mặt nhựa đường bong tróc do xe cộ qua lại thường xuyên, tạo thành lỗ hổng trên mặt đường."
t["434"] = "Nếu bật máy sưởi hoặc điều hòa ở chế độ tuần hoàn không khí bên trong thì kính cửa trong xe có thể bị mờ hơi nước nặng hơn, nên hãy bật ở chế độ lấy gió từ bên ngoài."
t["435"] = "Vì quãng đường phanh dài ra nên hãy giữ khoảng cách với xe phía trước gấp hơn 2 lần bình thường để phòng ngừa tai nạn va chạm. Khi đi qua khu vực ngập nước, nếu dừng lại giữa chừng thì nước mưa có thể tràn vào ống xả làm chết máy, nên tốt nhất là đi qua mà không dừng lại nếu có thể. Khi đỗ xe, hãy tránh những nơi có nguy cơ ngập cao như ven sông, gần suối, và tốt nhất nên đỗ ở nơi cao. Đỗ xe bên cạnh bức tường có nguy cơ sập hoặc dưới biển quảng cáo lớn cũng có thể nguy hiểm nên hãy tránh. Xe đỗ ở không gian tầng hầm của tòa nhà dự kiến bị ngập thì hãy di chuyển đến nơi an toàn."
t["436"] = "Phải dọn hết tuyết đọng ở mọi bộ phận của xe rồi mới chạy mới an toàn. Đặc biệt, tuyết ở phần nắp ca-pô phía trước có nguy cơ che khuất tầm nhìn nên việc dọn tuyết ở phần trước xe rồi mới lái càng quan trọng hơn."
t["437"] = "① Tùy tình huống, trên đường mưa hãy giảm tốc độ 20% so với tốc độ giới hạn, và giảm từ 50% trở lên khi tầm nhìn trong vòng 100 mét do mưa lớn v.v. ② Để không làm bắn nước vào người đi đường, hãy giữ khoảng cách từ 1 mét trở lên khi chạy. ③ Vào lúc mới bắt đầu mưa, để phòng trơn trượt phát sinh khi bụi bẩn hoặc tạp chất trên mặt đường quyện với nước mưa, tốt nhất nên lái ở trạng thái creep (bò), tức là để bánh xe lăn mà không đạp chân ga và chân phanh. ④ Ngay cả khi lái xe vào ban ngày, tốt nhất cũng nên bật đèn hậu và đèn pha."
t["438"] = "Đèn pha (đèn chiếu xa) bị tán xạ do các hạt nước trong sương mù nên không bật, mà hãy bật đèn cốt (đèn chiếu gần) hoặc đèn sương mù."
t["439"] = "Điều 19 Thông tư thi hành Luật Giao thông đường bộ (Tốc độ của xe cơ giới v.v.) khoản 2: khi thời tiết xấu do mưa, sương mù, tuyết v.v., dù đã có quy định tại khoản 1 vẫn phải giảm tốc độ lái xe theo các tiêu chuẩn ở từng mục sau."
t["440"] = "Cây lớn có khả năng bị sét đánh cao, và khi đó cây đổ xuống có khả năng gây tai nạn cao nên tốt nhất nên tránh, và cho dù xe có bị sét đánh thì bên trong xe vẫn an toàn hơn bên ngoài."
t["441"] = "④ Điều 9 Luật Địa chỉ theo tên đường (Lắp đặt biển tên đường và biển số cơ sở) khoản 1 - Thị trưởng thành phố tự trị đặc biệt, Tỉnh trưởng tỉnh tự trị đặc biệt và Thị trưởng, Huyện trưởng, Quận trưởng phải lắp đặt biển tên đường và biển số cơ sở tại những nơi cần thiết để hướng dẫn địa chỉ theo tên đường hoặc hỗ trợ hoạt động cứu hộ, cứu nạn."
t["442"] = "Khi bị chói mắt bởi đèn pha của xe đi ngược chiều, tốt nhất không nhìn thẳng vào ánh đèn pha mà nhìn về phía mép phải của đường trong khi lái xe."
t["443"] = "Điều 66 Luật Giao thông đường bộ, Điều 40 Thông tư thi hành Luật Giao thông đường bộ. Biển báo xe hỏng."
t["444"] = "Điều 37 Luật Giao thông đường bộ (Đèn của xe và tàu điện mặt đất) khoản 1: mọi người lái xe trong trường hợp thuộc một trong các mục sau phải bật đèn pha, đèn định vị chiều rộng xe, đèn hậu và các đèn khác theo quy định của Nghị định của Tổng thống."
t["445"] = "Điều 66 Luật Giao thông đường bộ (Xử lý khi hỏng xe v.v.), Điều 67 (Nghĩa vụ tuân thủ của người lái trên đường cao tốc v.v.), Điều 40 Thông tư thi hành Luật Giao thông đường bộ (Biển báo xe hỏng). Nếu xe hỏng có thể di chuyển được thì hãy đưa ra lề đường và yêu cầu trợ giúp từ nơi an toàn."
t["446"] = "Khi vô lăng bị lệch về một bên thì khả năng cao là lốp trước bị thủng, nên nếu đạp phanh chân thì khả năng cao xe sẽ chệch khỏi lộ trình."
t["447"] = "Theo Điều 40 Thông tư thi hành Luật Giao thông đường bộ (Biển báo xe hỏng), vào ban đêm trên đường cao tốc, cùng với biển tam giác an toàn phải lắp đặt thêm tín hiệu chớp sáng màu đỏ, đèn điện hoặc tín hiệu pháo sáng có thể nhận diện được từ điểm cách 500 mét về mọi phía."
t["448"] = "Khi lốp nổ, hãy tránh phanh gấp, giữ cho xe chạy thẳng, và sử dụng phanh động cơ để dừng lại ở nơi an toàn."
t["449"] = "Điều 67 Luật Giao thông đường bộ (Nghĩa vụ tuân thủ của người lái trên đường cao tốc v.v.) khoản 2: người lái xe chạy trên đường cao tốc v.v., để đảm bảo an toàn giao thông và lưu thông thông suốt, phải luôn trang bị biển báo xe hỏng theo Điều 66, và khi không thể vận hành xe do hỏng hóc hoặc lý do bất khả kháng khác thì phải dừng xe ở mép phải của đường và lắp đặt biển báo đó theo quy định của Thông tư của Bộ Nội vụ và An toàn."
t["450"] = "Đối với khu vực thi công, tùy từng đoạn được giới hạn 80 km/h và 60 km/h nên phải nhận biết biển báo giới hạn tốc độ và giảm tốc độ đầy đủ khi lái xe. (Hướng dẫn quản lý giao thông công trường đường bộ của Bộ Đất đai, Tiêu chuẩn quản lý giao thông công trường đường cao tốc)"

